406	// ---- The registry ----
407	
408	const defs = new Map<string, CommandDef>();
409	
410	function seed(): void {
411	  defs.clear();
412	  for (const d of SEED_COMMANDS) defs.set(d.name, d);
413	}
414	seed();
415	
416	/** Registers a command; a later def with the same name overrides it (a theme's override). */
417	export function registerCommand(def: CommandDef): void {
418	  defs.set(def.name, def);
419	}
420	
421	export function commandByName(name: string): CommandDef | undefined {
422	  return defs.get(name);
423	}
424	
425	/** Every registered command, by name (tests, the gallery). */
426	export function allCommands(): CommandDef[] {
427	  return [...defs.values()].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
428	}
429	
430	/** Back to the seed commands (a theme switch, tests). */
431	export function resetCommands(): void {
432	  seed();
433	}
