  const arriving = out.filter((d) => ARRIVING.has(d.rule.id));
  if (arriving.length >= CROWD_MIN) for (const d of arriving) d.attends = 0;
  sweepCreations(out, f, rules);
  joinVolleys(out, f, dir);
  arcsOf(out);
  turnVolleys(out, f);
  applyLimelight(out, ll);
