  };
  // The sector sweep (27 E7) goes first, at 0: it brings its pieces in, so anything else that casts one
  // of them starts once it ends (an underway would carve a piece still hidden). Its seats don't hold anyone back.
  const sweep = drafts.find((d) => d.sweep);
  if (sweep) at(sweep, 0);
  const sweptKeys = new Set(sweep?.cast.subject ?? []);
  const swept = (d: Draft) => (sweep && d !== sweep && shares(d.all, sweptKeys) ? end(sweep) : 0);
  // What brings a protected moment's cast member into the scene goes first, in event order: a
  // facility's jump-in, then the attachment's opening, ahead of its merge.
  const ahead = drafts.filter((s) => !s.protect && s.rule.introduces && drafts.some((d) => d.protect && (s.cast.subject ?? []).some((k) => d.all.has(k))));
  const placed: Draft[] = sweep ? [sweep] : [];
  for (const d of ahead) {
    at(d, Math.max(0, swept(d), ...waited(d, placed), ...crewBusy(d, placed, seq)));
    placed.push(d);
  }
  // Moments that lead (a merge) go next, then the rest, each in event order. A close inside an arc
  // (22 C4) plays at its merge's impact, whatever the merge holds.
  const moments: Draft[] = [...ahead];
  const order = drafts.filter((d) => d.protect && !d.arc?.merge).sort((a, b) => Number(!!b.rule.leads) - Number(!!a.rule.leads));
  for (const d of order) {
    at(d, Math.max(0, swept(d), ...moments.filter((p) => blocks(p, d)).map((p) => blockedUntil(p, d, seq)), ...crewBusy(d, moments, seq)));
    moments.push(d);
    for (const c of drafts.filter((x) => x.arc?.merge === d)) {
      c.startMs = d.startMs + phaseStart(d.phases, 'echo') + ARC_IMPACT_MS;
      timed.push(c);
      moments.push(c);
    }
  }
  const flown: Draft[] = [...moments];
  for (const d of drafts) {
    if (d === sweep) continue;
    if (!d.protect && !ahead.includes(d)) {
      at(d, Math.max(0, swept(d), ...moments.filter((p) => p.protect && blocks(p, d)).map((p) => blockedUntil(p, d, seq)), ...waited(d, placed), ...crewBusy(d, flown, seq)));
      flown.push(d);
    }
    if (!ahead.includes(d)) placed.push(d);
  }
}

/** Where a phase starts among `phases` (or where the last ends, if it has none). */
const phaseStart = (phases: readonly PhaseSpan[], phase: string) => phases.find((p) => p.phase === phase)?.atMs ?? Math.max(0, ...phases.map((p) => p.atMs + p.durMs));

/** The shape a beat's maneuvers give it: each event's earliest start (non-zero only), and the whole. */
export function shapeOf(h: ScopeHistory, events: readonly AnyTimelineEvent[], f: RoundFacts, rules: readonly ManeuverRule[] = PACE_RULES, prio: Prio = basePriority, ll?: Limelight, seq: SequenceOptions = SEQUENCE_ON): BeatShape {
  const drafts = draftsOf(h, events, f, rules, prio, ll);
  sequence(drafts, seq);
  const first = new Map<string, number>();
  let durationMs = 0;
  // A labelled one holds the beat open for its note's reading time too (22 B7), so the next beat's
  // never competes with it.
  for (const d of drafts) {
    first.set(d.e.eventKey, Math.min(first.get(d.e.eventKey) ?? Infinity, d.startMs));
    durationMs = Math.max(durationMs, d.startMs + heldMs(d));
  }
  const afterMs = new Map([...first].filter(([, ms]) => ms > 0));
  const essential = drafts.some((d) => d.rule.tier === 'essential');
  return { afterMs, durationMs, ...(essential ? { essential } : {}) };
}
  }
  return out;
}

/** What a waiting maneuver waited for, inferred from the plan (the engine's own queue is private). */
export interface Binding { pred: PlannedManeuver; cause: Exclude<Cause, 'other'>; anchor: 'end' | 'noteEnd' | 'claim' | 'seam' | 'near' }

/** The binding predecessor of a maneuver in its beat, with the cause and which of its ends it matches; null when none. */
export function bindingOf(m: PlannedManeuver, beatMs: PlannedManeuver[]): Binding | null {
  const nm = (x: PlannedManeuver) => Math.max(x.durationMs, NOTE_MIN_MS);
  // A wait on attention places travels while it waits (27 E2): it sets off so its act (its claim) lands as the places free.
  const claimAt = m.afterMs + claimMs(m.phases);
  // The built overlaps (27 E4), from the sequencer's own functions so the ledger can't drift: P3's seam (a
  // wait through a hold, sharing no actor at the act) and P4's near start (the same person flown twice).
  const actors = (x: PlannedManeuver) => ACTING_ROLES.flatMap((r) => x.cast[r] ?? []) as string[];
  const seamAt = (x: PlannedManeuver) => seamStartMs(endOf(x), tailOf(x.phases), claimMs(m.phases));
  const nearAt = (x: PlannedManeuver) => nearStartMs(x.afterMs, workEndOf(x.phases), releaseOfPlay(x), gatherAtOf(m.phases));
  const anchorOf = (x: PlannedManeuver): Binding['anchor'] | null =>
    Math.abs(endOf(x) - m.afterMs) < 0.5 ? 'end'
      : Math.abs(x.afterMs + nm(x) - m.afterMs) < 0.5 ? 'noteEnd'
        : Math.abs(x.afterMs + nm(x) - claimAt) < 0.5 ? 'claim'
          : !shares(actors(m), actors(x)) && Math.abs(seamAt(x) - m.afterMs) < 0.5 ? 'seam'
            : shares(crew(m), crew(x)) && flyingPlay(m) && flyingPlay(x) && Math.abs(nearAt(x) - m.afterMs) < 0.5 ? 'near' : null;
  const preds = beatMs.filter((x) => x !== m && anchorOf(x))
    .sort((a, b) => endOf(b) - endOf(a) || cmp(a.eventKey + a.id, b.eventKey + b.id));
  const p = preds[0];
  if (!p) return null;
  const anchor = anchorOf(p)!;
  if (anchor === 'claim') return { pred: p, cause: 'P-6', anchor };
  if (anchor === 'near' || shares(crew(m), crew(p))) return { pred: p, cause: 'P-5', anchor };
  if ((m.protect || p.protect) && (shares(castKeys(m), castKeys(p)) || shares(m.holds ?? [], castKeys(p)) || shares(p.holds ?? [], castKeys(m)))) return { pred: p, cause: 'P-3', anchor };
  const rule = (PACE_RULES as readonly PaceRule[]).find((r) => r.id === m.id);
  if (rule?.waitsFor?.includes(p.id) && p.eventKey === m.eventKey) return { pred: p, cause: 'P-4', anchor };
  return { pred: p, cause: 'P-6', anchor };
}

/** The cause a maneuver waited, inferred from the plan. */
function causeOf(m: PlannedManeuver, beatMs: PlannedManeuver[]): Cause {
  return bindingOf(m, beatMs)?.cause ?? 'other';
}

// The pacing ledger's Built section (v1.4 E1+): what each built E item actually saved per pod, set beside
// C2's estimate. Each item gives `before`: today's rules with that item's change undone, so the saving is a
// real re-schedule (`scheduleOf`) and not a model. Later E items add their own entry (method P or F items
// need a different hook and are not handled here). Pure and deterministic, like the ledger it extends.
import { PACE_RULES, RULE, phases, shortForm, type PaceRule } from '../src/shared/engine/pace';
import { resolvePods, scheduleOf, type EngineInputs } from './pacing-ledger';

export interface BuiltItem {
  id: string;
  name: string;
  /** Today's rules with this item's change undone. */
  before?: (rules: PaceRule[]) => PaceRule[];
  /** Engine inputs `before` runs with (an item built into the sequencer, undone by an option). */
  inputs?: Partial<EngineInputs>;
  /** Today's rules for the "now" run, when the item is a ceiling over them (E4d). */
  after?: (rules: PaceRule[]) => PaceRule[];
  /** The item is the director (27 E5): its "now" run directs, its "before" is `inputs`. Every other row runs undirected, as it was measured. */
  directs?: true;
  /** Engine inputs both runs take (27 E6: the director's rows built before volleys run without them, as they were measured). */
  both?: Partial<EngineInputs>;
  /** The item runs with the sector sweep (27 E7) in today's rules; every item built before it runs both schedules without it, as it was measured. */
  sweeps?: true;
  /** The item runs with rising tempo (27 E8); every item built before it runs both schedules without it, as it was measured. */
  rises?: true;
  /** The item runs with late-day montage (27 E10); every item built before it runs both schedules without it, as it was measured. */
  late?: true;
  /** C2's estimate of the saving, ms, per pod label. */
  estimateMs: Record<string, number>;
}

export interface BuiltRow { id: string; pod: string; beforeMs: number; nowMs: number; savedMs: number; estimateMs: number; diffMs: number }

