 * act's start, once its cast has arrived. The tell and the gather (travel) ask for no places. 0 if
 * there is no act.
 */
export const claimMs = (phases: readonly PhaseSpan[]): number => phases.find((x) => x.phase === 'act')?.atMs ?? 0;

/**
