        last.to = now;
        if (last.at && a.at) last.moved = Math.max(last.moved, Math.hypot(a.at.x - last.at.x, a.at.y - last.at.y));
      } else list.push({ from: now, to: now, moved: 0, at: a.at });
      episodes.set(a.pk, list);
      if (a.over) overWork++;
      opens++;
